/*
 * Podcasty — Native Android Port of "Youtube Music Download" (yt-dlp HTTP Audio Downloader + PostProcessor)
 *
 * Implements the "Youtube Music Download" flow:
 * 1. Resolves the best audio-only stream for a YouTube video (M4A / Opus) via YTmusicapi + yt-dlp client profiles.
 * 2. Simultaneously runs the integrated "caption extractor android" (YouTubeCaptionExtractorClient) to extract
 *    autogenerated or manual timestamped captions and format them into synchronized LRC lyrics.
 * 3. Downloads the YouTube audio stream using yt-dlp's chunked HTTP Range downloader (`HttpFD` in `http.py`)
 *    into a local audio file (`.m4a` / `.ogg`), avoiding YouTube bandwidth throttling.
 * 4. Post-processes the downloaded audio file via TagLib to embed the Title, Artist, Album, Artwork Thumbnail,
 *    and the synchronized LRC captions (`LYRICS` & `UNSYNCEDLYRICS`) directly inside the audio file
 *    (plus a sidecar `.lrc` file).
 * 5. Updates the library episode with the local downloaded audio file URI and embedded transcript so it plays
 *    automatically in Podcasty's music player with synchronized lyrics.
 */
package com.podcasty.app.podcast

import android.content.Context
import android.net.Uri
import android.os.ParcelFileDescriptor
import com.kyant.taglib.Picture
import com.kyant.taglib.TagLib
import com.podcasty.app.streaming.YouTubeAudioStream
import com.podcasty.app.streaming.YouTubeAudioStreamResolver
import com.podcasty.app.streaming.YouTubeAudioTrackOption
import com.podcasty.ytmusicapi.YouTubeAudioTrackKind
import kotlinx.coroutines.CancellationException
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.async
import kotlinx.coroutines.coroutineScope
import kotlinx.coroutines.currentCoroutineContext
import kotlinx.coroutines.delay
import kotlinx.coroutines.ensureActive
import kotlinx.coroutines.withContext
import okhttp3.OkHttpClient
import okhttp3.Request
import java.io.File
import java.io.RandomAccessFile
import java.util.concurrent.TimeUnit
import kotlin.random.Random

data class YouTubeAudioDownloadProgress(
    val videoId: String,
    val stage: String,
    val downloadedBytes: Long = 0L,
    val totalBytes: Long = 0L,
    val fraction: Float = 0f,
)

data class YouTubeDownloadedAudioBundle(
    val videoId: String,
    val audioFile: File,
    val audioFileUri: String,
    val artworkFile: File?,
    val sidecarLrcFile: File?,
    val extractedTranscript: ExtractedYouTubeTranscript?,
    val embeddedLrc: String?,
    val mimeType: String,
    val codec: String = "",
    val bitrateKbps: Int,
    val sampleRateHz: Int = 44_100,
    val audioChannels: Int = 2,
    val durationMs: Long,
    val tagsEmbeddedInFile: Boolean,
    val audioLanguageCode: String? = null,
    val audioTrackId: String? = null,
    val audioTrackDisplayName: String? = null,
    val audioTrackKind: YouTubeAudioTrackKind = YouTubeAudioTrackKind.UNKNOWN,
    val isOriginalAudio: Boolean = false,
    val isAutoDubbed: Boolean = false,
    val availableTracks: List<YouTubeAudioTrackOption> = emptyList(),
)

class YouTubeMusicDownloadManager(
    private val context: Context,
    private val audioStreamResolver: YouTubeAudioStreamResolver = YouTubeAudioStreamResolver(),
    private val captionExtractorClient: YouTubeCaptionExtractorClient = YouTubeCaptionExtractorClient(),
    private val httpClient: OkHttpClient = OkHttpClient.Builder()
        .connectTimeout(20, TimeUnit.SECONDS)
        .readTimeout(35, TimeUnit.SECONDS)
        .followRedirects(true)
        .followSslRedirects(true)
        .build(),
) {
    private val downloadDir: File by lazy {
        File(context.filesDir, "youtube_downloads").apply { mkdirs() }
    }

    /**
     * Executes the complete "Youtube Music Download" pipeline for [metadata]:
     * - Downloads the YouTube video as a local audio file (`.m4a` / `.ogg`) using chunked HTTP Range requests.
     * - Extracts autogenerated/manual captions via "caption extractor android" in parallel.
     * - Embeds the extracted synced `.lrc` captions, metadata tags, and cover artwork directly into the audio file.
     */
    suspend fun downloadAudioAndEmbedCaptions(
        metadata: YouTubeVideoMetadata,
        preferredLanguage: String,
        preferredAudioTrackId: String? = null,
        configuredBackendUrl: String = "",
        authToken: String? = null,
        existingTranscript: ExtractedYouTubeTranscript? = null,
        onProgress: (YouTubeAudioDownloadProgress) -> Unit = {},
    ): Result<YouTubeDownloadedAudioBundle> = withContext(Dispatchers.IO) {
        runCatching {
            val videoId = metadata.videoId.trim()
            onProgress(
                YouTubeAudioDownloadProgress(
                    videoId = videoId,
                    stage = "Inspecting audio tracks & resolving original audio…",
                    fraction = 0.05f,
                ),
            )

            coroutineScope {
                // Run caption extraction ("caption extractor android") and stream resolution concurrently
                val captionDeferred = async {
                    existingTranscript ?: run {
                        val res = captionExtractorClient.extractCaptions(
                            videoId = videoId,
                            languageCode = preferredLanguage,
                            configuredBackendUrl = configuredBackendUrl,
                            authToken = authToken,
                        )
                        (res as? YouTubeCaptionExtractionResult.Success)?.transcript
                    }
                }
                val streamDeferred = async {
                    audioStreamResolver.resolve(videoId, preferredAudioTrackId).getOrThrow()
                }
                val artworkDeferred = async {
                    downloadThumbnailIfAvailable(videoId, metadata.thumbnailUrl)
                }

                val stream = streamDeferred.await()
                val ext = resolveAudioExtension(stream.mimeType)
                val trackSuffix = buildTrackFileSuffix(stream)
                val titlePart = sanitizeFileName(metadata.title).take(55).trim().trimEnd('_')
                val safeBaseName = if (titlePart.isNotBlank()) {
                    "${titlePart}_${videoId}_$trackSuffix"
                } else {
                    "youtube_${videoId}_$trackSuffix"
                }
                val finalAudioFile = File(downloadDir, "$safeBaseName.$ext")
                val partAudioFile = File(downloadDir, "$safeBaseName.$ext.part")

                val trackBadge = stream.audioTrackDisplayName
                    ?: stream.audioLanguageCode?.uppercase()
                    ?: "Original audio"
                onProgress(
                    YouTubeAudioDownloadProgress(
                        videoId = videoId,
                        stage = "Selected $trackBadge (${stream.codec.ifBlank { ext.uppercase() }} ${stream.bitrateKbps} kbps) · Downloading…",
                        fraction = 0.09f,
                    ),
                )

                // Download the audio stream to disk using yt-dlp's chunked HTTP Range downloader (HttpFD)
                downloadStreamChunked(
                    videoId = videoId,
                    stream = stream,
                    partFile = partAudioFile,
                    finalFile = finalAudioFile,
                    onProgress = onProgress,
                )

                val transcript = captionDeferred.await()
                val lrcText = transcript?.takeIf { it.cues.isNotEmpty() }?.toLrcContent()
                val artworkPair = artworkDeferred.await()

                onProgress(
                    YouTubeAudioDownloadProgress(
                        videoId = videoId,
                        stage = if (lrcText != null) {
                            "Embedding synced captions (${transcript.cues.size} lines) & metadata into audio file…"
                        } else {
                            "Embedding metadata & artwork into downloaded audio file…"
                        },
                        downloadedBytes = finalAudioFile.length(),
                        totalBytes = finalAudioFile.length(),
                        fraction = 0.94f,
                    ),
                )

                // Write sidecar .lrc file alongside the downloaded audio file
                val sidecarFile = if (!lrcText.isNullOrBlank()) {
                    File(downloadDir, "$safeBaseName.lrc").apply {
                        writeText(lrcText, Charsets.UTF_8)
                    }
                } else {
                    null
                }

                // Embed metadata + autogenerated LRC captions + thumbnail directly into the audio file via TagLib
                val tagsEmbedded = embedMetadataAndCaptionsIntoFile(
                    audioFile = finalAudioFile,
                    metadata = metadata,
                    stream = stream,
                    lrcLyrics = lrcText,
                    artworkBytes = artworkPair?.second,
                )

                onProgress(
                    YouTubeAudioDownloadProgress(
                        videoId = videoId,
                        stage = "Downloaded $trackBadge & embedded metadata",
                        downloadedBytes = finalAudioFile.length(),
                        totalBytes = finalAudioFile.length(),
                        fraction = 1.0f,
                    ),
                )

                YouTubeDownloadedAudioBundle(
                    videoId = videoId,
                    audioFile = finalAudioFile,
                    audioFileUri = Uri.fromFile(finalAudioFile).toString(),
                    artworkFile = artworkPair?.first,
                    sidecarLrcFile = sidecarFile,
                    extractedTranscript = transcript,
                    embeddedLrc = lrcText,
                    mimeType = stream.mimeType,
                    codec = stream.codec,
                    bitrateKbps = stream.bitrateKbps,
                    sampleRateHz = stream.sampleRateHz,
                    audioChannels = stream.audioChannels,
                    durationMs = metadata.durationMs.takeIf { it > 0L } ?: stream.durationMs,
                    tagsEmbeddedInFile = tagsEmbedded,
                    audioLanguageCode = stream.audioLanguageCode,
                    audioTrackId = stream.audioTrackId,
                    audioTrackDisplayName = stream.audioTrackDisplayName,
                    audioTrackKind = stream.audioTrackKind,
                    isOriginalAudio = stream.isOriginalAudio,
                    isAutoDubbed = stream.isAutoDubbed,
                    availableTracks = stream.availableTracks,
                )
            }
        }
    }

    /**
     * Port of `Youtube Music Download/yt_dlp/downloader/http.py::HttpFD.real_download`.
     * Downloads the audio stream in randomized ~9.5-10 MB HTTP Range chunks with `Accept-Encoding: identity`
     * to a `.part` temporary file, then atomically renames it to [finalFile].
     */
    private suspend fun downloadStreamChunked(
        videoId: String,
        stream: YouTubeAudioStream,
        partFile: File,
        finalFile: File,
        onProgress: (YouTubeAudioDownloadProgress) -> Unit,
    ) {
        if (finalFile.exists() && finalFile.length() > 64_000L) {
            onProgress(
                YouTubeAudioDownloadProgress(
                    videoId = videoId,
                    stage = "Using cached downloaded audio file…",
                    downloadedBytes = finalFile.length(),
                    totalBytes = finalFile.length(),
                    fraction = 0.90f,
                ),
            )
            return
        }
        if (partFile.exists()) {
            partFile.delete()
        }

        var downloadedBytes = 0L
        var totalContentLength = -1L
        val baseChunkSize = DefaultHttpChunkSize

        RandomAccessFile(partFile, "rw").use { raf ->
            var retries = 0
            while (true) {
                if (totalContentLength in 1..downloadedBytes) break

                // Randomized 95%..100% chunk size just like yt-dlp HttpFD (`random.randint(int(chunk_size * 0.95), chunk_size)`)
                val chunkSpan = Random.nextLong((baseChunkSize * 95) / 100, baseChunkSize + 1)
                val rangeStart = downloadedBytes
                val rangeEnd = if (totalContentLength > 0L) {
                    minOf(rangeStart + chunkSpan - 1L, totalContentLength - 1L)
                } else {
                    rangeStart + chunkSpan - 1L
                }

                val request = Request.Builder()
                    .url(stream.url)
                    .get()
                    .header("Accept-Encoding", "identity")
                    .header("User-Agent", MobileDownloadUserAgent)
                    .header("Range", "bytes=$rangeStart-$rangeEnd")
                    .build()

                val chunkResult = runCatching {
                    httpClient.newCall(request).execute().use { response ->
                        if (response.code == 416) {
                            // Requested range not satisfiable -> download finished
                            return@use -1L
                        }
                        if (!response.isSuccessful && response.code != 206) {
                            throw IllegalStateException("Audio download failed (HTTP ${response.code})")
                        }

                        if (totalContentLength <= 0L) {
                            totalContentLength = parseTotalLengthFromContentRange(response.header("Content-Range"))
                                ?: response.header("Content-Length")?.toLongOrNull()
                                ?: -1L
                        }

                        val body = response.body ?: throw IllegalStateException("Empty audio response body")
                        val buffer = ByteArray(32 * 1024)
                        var chunkRead = 0L
                        var lastProgressEmitMs = 0L
                        raf.seek(rangeStart)
                        body.byteStream().use { input ->
                            while (true) {
                                currentCoroutineContext().ensureActive()
                                val read = input.read(buffer)
                                if (read <= 0) break
                                raf.write(buffer, 0, read)
                                chunkRead += read
                                val nowMs = System.currentTimeMillis()
                                if (nowMs - lastProgressEmitMs >= 250L) {
                                    lastProgressEmitMs = nowMs
                                    val currentTotal = rangeStart + chunkRead
                                    val frac = if (totalContentLength > 0L) {
                                        (0.10f + 0.80f * (currentTotal.toFloat() / totalContentLength.toFloat())).coerceIn(0.10f, 0.90f)
                                    } else {
                                        0.50f
                                    }
                                    val mbDone = "%.1f".format(currentTotal / (1024f * 1024f))
                                    val mbTotal = if (totalContentLength > 0L) {
                                        " / %.1f MB".format(totalContentLength / (1024f * 1024f))
                                    } else {
                                        " MB"
                                    }
                                    onProgress(
                                        YouTubeAudioDownloadProgress(
                                            videoId = videoId,
                                            stage = "Downloading YouTube audio ($mbDone$mbTotal)…",
                                            downloadedBytes = currentTotal,
                                            totalBytes = totalContentLength.coerceAtLeast(currentTotal),
                                            fraction = frac,
                                        ),
                                    )
                                }
                            }
                        }
                        // If server ignored Range and returned 200 OK full response, we're done after this stream
                        if (response.code == 200 && response.header("Content-Range") == null) {
                            totalContentLength = rangeStart + chunkRead
                        }
                        chunkRead
                    }
                }

                if (chunkResult.isSuccess) {
                    val bytesRead = chunkResult.getOrThrow()
                    if (bytesRead <= 0L) break
                    downloadedBytes += bytesRead
                    retries = 0
                    if (totalContentLength > 0L && downloadedBytes >= totalContentLength) {
                        break
                    }
                } else {
                    val err = chunkResult.exceptionOrNull()
                    if (err is CancellationException) throw err
                    retries++
                    if (retries > 3) {
                        throw err ?: IllegalStateException("Audio download interrupted.")
                    }
                    // Exponential backoff avoids tight radio/CPU retry loops on transient network drops
                    delay(1_000L * (1 shl (retries - 1)))
                }
            }
        }

        if (!partFile.exists() || partFile.length() <= 0L) {
            throw IllegalStateException("Downloaded audio file was empty.")
        }
        if (finalFile.exists()) {
            finalFile.delete()
        }
        if (!partFile.renameTo(finalFile)) {
            partFile.copyTo(finalFile, overwrite = true)
            partFile.delete()
        }
    }

    /**
     * Post-processor that embeds Title, Artist, Album, Comment, Artwork Picture, and the
     * autogenerated synced LRC captions (`LYRICS` and `UNSYNCEDLYRICS`) directly into [audioFile] via TagLib.
     */
    internal fun embedMetadataAndCaptionsIntoFile(
        audioFile: File,
        metadata: YouTubeVideoMetadata,
        stream: YouTubeAudioStream,
        lrcLyrics: String?,
        artworkBytes: ByteArray?,
    ): Boolean {
        return runCatching {
            val existingMap = ParcelFileDescriptor.open(audioFile, ParcelFileDescriptor.MODE_READ_ONLY).use { pfd ->
                TagLib.getMetadata(pfd.dup().detachFd(), false)?.propertyMap ?: hashMapOf()
            }
            val nextMap = HashMap<String, Array<String>>(existingMap)
            nextMap["TITLE"] = arrayOf(metadata.title.ifBlank { stream.title.ifBlank { "YouTube Audio" } })
            nextMap["ARTIST"] = arrayOf(metadata.channelName.ifBlank { stream.channelName.ifBlank { "YouTube" } })
            nextMap["ALBUM"] = arrayOf("YouTube Audio · ${metadata.channelName.ifBlank { "Podcasty" }}")
            nextMap["ALBUMARTIST"] = arrayOf(metadata.channelName.ifBlank { "YouTube" })
            nextMap["GENRE"] = arrayOf("YouTube Podcast")
            nextMap["COMMENT"] = arrayOf(metadata.canonicalUrl)
            stream.audioLanguageCode?.takeIf { it.isNotBlank() }?.let { lang ->
                nextMap["LANGUAGE"] = arrayOf(lang)
            }
            stream.audioTrackDisplayName?.takeIf { it.isNotBlank() }?.let { trackLabel ->
                nextMap["AUDIO_TRACK"] = arrayOf(trackLabel)
            }
            stream.audioTrackId?.takeIf { it.isNotBlank() }?.let { trackId ->
                nextMap["AUDIO_TRACK_ID"] = arrayOf(trackId)
            }
            if (!lrcLyrics.isNullOrBlank()) {
                nextMap["LYRICS"] = arrayOf(lrcLyrics)
                nextMap["UNSYNCEDLYRICS"] = arrayOf(lrcLyrics)
            }

            val savedProps = ParcelFileDescriptor.open(audioFile, ParcelFileDescriptor.MODE_READ_WRITE).use { pfd ->
                TagLib.savePropertyMap(pfd.dup().detachFd(), nextMap)
            }
            if (artworkBytes != null && artworkBytes.isNotEmpty()) {
                val picture = Picture(
                    data = artworkBytes,
                    description = "Front Cover",
                    pictureType = "Front Cover",
                    mimeType = "image/jpeg",
                )
                ParcelFileDescriptor.open(audioFile, ParcelFileDescriptor.MODE_READ_WRITE).use { pfd ->
                    TagLib.savePictures(pfd.dup().detachFd(), arrayOf(picture))
                }
            }
            savedProps
        }.getOrDefault(false)
    }

    private fun downloadThumbnailIfAvailable(videoId: String, thumbnailUrl: String?): Pair<File, ByteArray>? {
        val url = thumbnailUrl?.takeIf { it.isNotBlank() }
            ?: "https://i.ytimg.com/vi/$videoId/hqdefault.jpg"
        return runCatching {
            val req = Request.Builder().url(url).get().build()
            httpClient.newCall(req).execute().use { resp ->
                if (!resp.isSuccessful) return null
                val bytes = resp.body?.bytes() ?: return null
                if (bytes.isEmpty()) return null
                val file = File(downloadDir, "${videoId}_cover.jpg")
                file.writeBytes(bytes)
                file to bytes
            }
        }.getOrNull()
    }

    companion object {
        private const val DefaultHttpChunkSize = 9L * 1024L * 1024L // ~9 MB Range chunks
        private const val MobileDownloadUserAgent =
            "com.google.ios.youtube/21.26.4 (iPhone16,2; U; CPU iOS 18_3_2 like Mac OS X;)"

        internal fun parseTotalLengthFromContentRange(contentRange: String?): Long? {
            if (contentRange.isNullOrBlank()) return null
            // Format: "bytes 0-9437183/39673820"
            val slashIdx = contentRange.lastIndexOf('/')
            if (slashIdx < 0 || slashIdx == contentRange.lastIndex) return null
            return contentRange.substring(slashIdx + 1).trim().toLongOrNull()
        }

        internal fun buildTrackFileSuffix(stream: YouTubeAudioStream): String {
            val langPart = (stream.audioLanguageCode ?: stream.audioTrackId ?: "default")
                .replace(Regex("[^A-Za-z0-9_-]+"), "_")
                .trim('_')
                .lowercase()
                .ifBlank { "default" }
            val kindPart = when {
                stream.isOriginalAudio -> "orig"
                stream.isAutoDubbed -> "autodub"
                else -> stream.audioTrackKind.name.lowercase()
            }
            return "${kindPart}_$langPart".take(28)
        }

        internal fun resolveAudioExtension(mimeType: String): String {
            val lower = mimeType.lowercase()
            return when {
                lower.contains("mp4") || lower.contains("m4a") || lower.contains("aac") -> "m4a"
                lower.contains("opus") || lower.contains("ogg") -> "ogg"
                lower.contains("webm") -> "webm"
                lower.contains("mpeg") || lower.contains("mp3") -> "mp3"
                else -> "m4a"
            }
        }

        internal fun sanitizeFileName(raw: String): String =
            raw.replace(Regex("[\\\\/:*?\"<>|\\p{Cntrl}]+"), "_")
                .replace(Regex("\\s+"), " ")
                .trim()
                .take(90)
    }
}
